<?php
namespace Database\Seeders;use App\Models\{Login,UserProfile,UserType};use Illuminate\Database\Seeder;use RuntimeException;
class AdminSeeder extends Seeder{public function run():void{$username=env('ADMIN_USERNAME','superadmin');$password=env('ADMIN_PASSWORD');if(app()->isProduction()&&!$password)throw new RuntimeException('ADMIN_PASSWORD must be set before production seeding.');$type=UserType::firstOrCreate(['type_code'=>'ADMIN'],['type_name'=>'Administrator','description'=>'System administrator','status'=>'1']);$login=Login::firstOrCreate(['username'=>$username],['password'=>$password?:'ChangeMe123!','status'=>1]);$login->assignRole('Super Admin');UserProfile::firstOrCreate(['reference_id'=>'ADM001'],['user_type_code'=>$type->id,'first_name'=>'Super','last_name'=>'Admin','is_verified'=>1,'login_id'=>$login->id,'status'=>'1']);}}
